configfiles.configfile:
set -eu
ref="\$1"; treefile="\$2"; output="\$3"; files="\$4"
pair_ids_file="\$5"; species_map_file="\$6"

[ -n "\$files" ] || { echo "no pairwise MAFs reached the job" >&2; exit 1; }
case "\$ref" in
    ''|[!A-Za-z]*|*[!A-Za-z0-9_]*|*maf*|*eof*)
        echo "reference name must be a letter then letters, digits or _, without maf or eof: \$ref" >&2
        exit 1
        ;;
esac

AWK=gawk
command -v gawk >/dev/null 2>&1 || AWK=awk

mkdir work
tree=`sed 's/:[-+0-9.eE]*//g; s/)[A-Za-z0-9_.-]*/)/g; s/;//; /^ *\$/d' "\$treefile" | tr '\n' ' ' | sed 's/ //g; s/,/ /g'`
leaves=" `echo "\$tree" | tr '()' '  ' | tr -s ' '` "
case "\$leaves" in *" \$ref "*) ;; *) echo "reference \$ref is not in the tree" >&2; exit 1;; esac

if [ -n "\$pair_ids_file" ]; then
    cat > resolve_roast.awk <<'AWK_EOF'
function trim(s) {
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", s)
    return s
}
function valid_species(sp) {
    return (sp ~ /^[A-Za-z][A-Za-z0-9_]*$/ && sp !~ /maf|eof/)
}
function map_species(raw) {
    if (raw in smap) return smap[raw]
    return raw
}
function resolve_query(pid,    i, n, sep, seps, pos, a, b, sa, sb, rest, mapped) {
    mapped = map_species(pid)
    if (mapped in leaf_set && mapped != ref) {
        return mapped
    }
    seps[1] = "__"
    seps[2] = "."
    seps[3] = "_"
    for (i = 1; i <= 3; i++) {
        sep = seps[i]
        pos = 1
        while (1) {
            rest = substr(pid, pos)
            n = index(rest, sep)
            if (n == 0) break
            a = substr(pid, 1, pos + n - 2)
            b = substr(pid, pos + n - 1 + length(sep))
            sa = map_species(a)
            sb = map_species(b)
            if (sa == ref && (sb in leaf_set) && sb != ref) return sb
            pos = pos + n
        }
    }
    return ""
}
BEGIN {
    nleaves = split(leaves_str, larr, /[[:space:]]+/)
    for (i = 1; i <= nleaves; i++) {
        if (larr[i] != "") leaf_set[larr[i]] = 1
    }
    if (species_map_file != "") {
        while ((getline line < species_map_file) > 0) {
            gsub(/\r$/, "", line)
            if (line == "" || line ~ /^#/) continue
            nf = split(line, cols, /\t/)
            if (nf >= 2) {
                k = trim(cols[1])
                v = trim(cols[2])
                if (k != "" && v != "") smap[k] = v
            }
        }
        close(species_map_file)
    }
    nf = split(paths_str, paths, /,/)
    ni = 0
    while ((getline line < ids_file) > 0) {
        gsub(/\r$/, "", line)
        line = trim(line)
        if (line == "") continue
        ni++
        ids[ni] = line
    }
    close(ids_file)
    if (ni != nf) {
        printf("pairwise_ids count (%d) != pairwise count (%d)\n", ni, nf) > "/dev/stderr"
        exit 1
    }
    for (i = 1; i <= nf; i++) {
        pid = ids[i]
        sp = resolve_query(pid)
        if (sp == "") {
            printf("cannot resolve query species in tree from pairwise identifier %s (ref=%s)\n", pid, ref) > "/dev/stderr"
            exit 1
        }
        if (!valid_species(sp)) {
            printf("species name %s (from %s) cannot go through roast\n", sp, pid) > "/dev/stderr"
            exit 1
        }
        printf("%s\t%s\n", sp, paths[i])
    }
}
AWK_EOF

    "\$AWK" -v ref="\$ref" \
        -v leaves_str="\$leaves" \
        -v paths_str="\$files" \
        -v ids_file="\$pair_ids_file" \
        -v species_map_file="\$species_map_file" \
        -f resolve_roast.awk > roast_plan.tsv
    while IFS='	' read -r name f; do
        [ -n "\$name" ] || continue
        if [ -e "work/\$ref.\$name.sing.maf" ]; then echo "\$name is given twice" >&2; exit 1; fi
        first_s1=`"\$AWK" '/^s[[:space:]]/{ print \$2; exit }' "\$f"`
        [ -n "\$first_s1" ] || continue
        p1="\$ref."
        p2="\$name."
        first_s2=`"\$AWK" '/^s[[:space:]]/{ c++; if (c == 2) { print \$2; exit } }' "\$f"`
        already_prefixed="no"
        case "\$first_s1|\$first_s2" in
            "\$p1"*"|\$p2"*) already_prefixed="yes" ;;
        esac
        exp_bytes=`"\$AWK" -v p1="\$p1" -v p2="\$p2" -v pre="\$already_prefixed" -v out="work/\$ref.\$name.sing.maf" '
            function die(m) { print "multiz_roast: " m > "/dev/stderr"; failed = 1; exit 1 }
            function endblock() {
                if (row != 2) die("block at line " bline " has " row " s line(s), expected 2")
                inblock = 0
            }
            function emit(s) { print s > out; nb += length(s) + 1 }
            function put_prefixed(pref,   lead) {
                match(\$0, /^s +/)
                lead = substr(\$0, 1, RLENGTH)
                emit(lead pref substr(\$0, RLENGTH + 1))
            }
            /^[[:space:]]*$/ {
                if (inblock) endblock()
                if (pre == "no") emit(\$0)
                next
            }
            /^a([[:space:]]|$)/ {
                if (inblock) endblock()
                inblock = 1; row = 0; bline = NR
                if (pre == "no") emit(\$0)
                next
            }
            /^s[[:space:]]/ {
                if (split(\$0, f, " ") != 7) die("s line at line " NR " does not have 7 fields")
                if (row == 0) {
                    q = f[2]
                    if (f[5] != "+") die("reference row at line " NR " is on the - strand")
                    if (q != cur) {
                        if (q in done) die("reference sequence " q " restarts at line " NR ": input MAF is not sorted")
                        if (cur != "") done[cur] = 1
                        cur = q; last = -1
                    }
                    if (f[3] + 0 < last) die("reference start goes backwards at line " NR ": " q " " f[3] " after " last)
                    last = f[3] + 0
                    if (pre == "no") put_prefixed(p1)
                } else if (row == 1) {
                    if (pre == "no") put_prefixed(p2)
                } else {
                    die("block at line " bline " has >2 s lines")
                }
                row++
                next
            }
            { if (pre == "no") emit(\$0) }
            END {
                if (failed) exit 1
                if (inblock) endblock()
                if (pre == "no" && close(out) != 0) die("failed writing " out)
                print nb + 0
            }
        ' "\$f"`
        if [ "\$already_prefixed" = "yes" ]; then
            ln -s "\$f" "work/\$ref.\$name.sing.maf"
        else
            got_bytes=`wc -c < "work/\$ref.\$name.sing.maf" | tr -d '[:space:]'`
            if [ "\$got_bytes" != "\$exp_bytes" ]; then
                echo "truncated write staging MAF for \$ref.\$name (expected \$exp_bytes bytes, got \$got_bytes)" >&2
                exit 1
            fi
        fi
    done < roast_plan.tsv
else
    IFS=','
    for f in \$files; do
        unset IFS
        name=`"\$AWK" -v ref="\$ref" '/^s /{ split(\$2, p, "."); if (p[1] != ref) { print p[1]; exit } }' "\$f"`
        IFS=','
        [ -n "\$name" ] || continue
        case "\$leaves" in *" \$name "*) ;; *) echo "\$name is not in the tree" >&2; exit 1;; esac
        if [ -e "work/\$ref.\$name.sing.maf" ]; then echo "\$name is given twice" >&2; exit 1; fi
        ln -s "\$f" "work/\$ref.\$name.sing.maf"
    done
    unset IFS
fi

n=0; t=0; none=''
for s in \$leaves; do
    [ "\$s" = "\$ref" ] && continue
    t=`expr \$t + 1`
    if [ -e "work/\$ref.\$s.sing.maf" ]; then
        n=`expr \$n + 1`
    else
        echo '\#\#maf version=1 scoring=autoMZ' > "work/\$ref.\$s.sing.maf"
        none="\$none \$s"
    fi
done
echo "species with blocks: \$n of \$t"
echo "species without blocks:\$none"
echo "tree: \$tree"
cd work
mkdir tmp
roast + T="\$PWD/tmp" E="\$ref" "\$tree" \$ref.*.sing.maf out.maf > /dev/null
cd ..
mv work/out.maf "\$output"
